        /* coverity[misra_c_2012_rule_11_5_violation] */
        px_Task_स्थितिः_Array = pv_पत्तनम्_Malloc( ux_Current_सङ्ख्या_सम्बन्धि_Tasks * परिमाण( Task_स्थितिः_t ) );

